$t['Automatic setup creates the webhook for this site URL only, or adds the missing events to it and keeps any other events. It saves the Webhook ID used to verify signatures. It never deletes webhooks, never touches other URLs and never changes the app permissions.'] = 'La configuration automatique crée le webhook uniquement pour l\'URL de ce site, ou y ajoute les événements manquants en conservant les autres. Elle enregistre le Webhook ID utilisé pour vérifier les signatures. Elle ne supprime jamais de webhooks, ne touche jamais aux autres URL et ne modifie jamais les autorisations de l\'application.';
$t['Automatic setup needs Webhook Endpoints: Write. It creates the webhook and securely saves its new signing secret, or enables the existing endpoint and adds missing events. It preserves existing events and does not replace endpoints or change API key permissions.'] = 'La configuration automatique nécessite Webhook Endpoints: Write. Elle crée le webhook et enregistre de manière sécurisée son nouveau secret de signature, ou active l\'endpoint existant et ajoute les événements manquants. Elle conserve les événements existants et ne remplace pas les endpoints ni ne modifie les autorisations de la clé API.';
