$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Le commit identifie la révision Git extraite sur ce serveur ; les modifications locales de fichiers ne sont pas incluses. Un tag Git est affiché lorsqu\'il pointe directement vers ce commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Le service Companion Chat n\'est pas disponible pour le moment. Demandez à l\'administrateur du site de vérifier la connexion du plugin IA.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'La connexion n\'a pas pu être renouvelée. Veuillez reconnecter votre compte.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'La connexion a expiré et n\'a pas pu être renouvelée. Veuillez reconnecter votre compte.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'La connexion à la destination a été coupée pendant la diffusion. Il peut s\'agir d\'un problème réseau temporaire ; FFMPEG va tenter de se reconnecter.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'La connexion à YouTube a été interrompue. L\'envoi a été mis en pause et peut être repris.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'La connexion a été interrompue. Vérifiez votre compte avant de réessayer cet abonnement.';
$t['The connection was renewed.'] = 'La connexion a été renouvelée.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'La fenêtre de connexion a été fermée avant la fin de l\'autorisation. Aucun compte n\'a été connecté.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Les fichiers convertis ont été conservés. Contactez l\'administrateur du site pour relancer le transfert ; vous n\'avez pas besoin de remettre en ligne la vidéo.';
$t['The converted video could not be sent back to this site.'] = 'La vidéo convertie n\'a pas pu être renvoyée vers ce site.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Les clients de la carte sélectionnée. Recherchez, triez, copiez les e-mails ou exportez le tout vers une feuille de calcul.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Le quota quotidien de mises en ligne YouTube de ce site a été atteint. Les mises en ligne seront de nouveau disponibles après minuit (heure du Pacifique). Veuillez réessayer plus tard.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'La version de la base de données ne change que lorsqu\'une migration de la base de données est appliquée. Il n\'est pas prévu qu\'elle corresponde au tag de version ou au commit.';
$t['The default'] = 'Par défaut';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Le serveur RTMP de destination a refusé la connexion. Vérifiez l\'URL du flux et assurez-vous que le serveur est en ligne.';
$t['The destination server requires authentication. Check the stream key.'] = 'Le serveur de destination exige une authentification. Vérifiez la clé de stream.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Le serveur de destination a renvoyé 403. La clé de stream est peut-être invalide ou expirée.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'La vidéo de destination a été supprimée ou ce compte ne peut pas la modifier. Vérifiez la vidéo et les accès du compte sur le site.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'L\'autorisation de téléchargement s\'applique à tout le site, il n\'y a donc rien à vérifier sur la vidéo';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = 'The email is invalid';
$t['The encoder could not download the original file.'] = 'L\'encodeur n\'a pas pu télécharger le fichier original.';
$t['The encoder could not find this video on the site.'] = 'L\'encodeur n\'a pas trouvé cette vidéo sur le site.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'L\'encodeur n\'a pas confirmé l\'ajout de la vidéo à la file d\'attente. Veuillez réessayer.';
$t['The encoder is running out of disk space'] = 'L\'encodeur manque d\'espace disque';
$t['The encoder reported an unexpected error.'] = 'L\'encodeur a signalé une erreur inattendue.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Le processus d\'encodage s\'est arrêté de manière inattendue et les nouvelles tentatives automatiques ont également échoué.';
$t['The encoding queue is stalled'] = 'La file d\'encodage est bloquée';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'L\'achat de l\'événement n\'a pas pu être finalisé. Le paiement n\'a pas été débité de votre portefeuille. Vérifiez votre solde avant de réessayer.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Le fichier n\'a pas pu être converti. Il est peut-être endommagé ou dans un format non pris en charge par l\'encodeur.';
$t['The file must be an .vtt file!'] = 'Le fichier doit se terminer par .vtt !';
$t['The file must be an .vtt or .srt file!'] = 'Le fichier doit être un fichier .vtt ou .srt !';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Le montant final est calculé selon la durée mesurée pendant le traitement. Un portefeuille Marketplace connecté est requis.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Le film suivant contient des éléments qui ne conviennent pas aux enfants de 17 ans et moins.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Le film suivant contient des éléments qui peuvent ne pas convenir aux enfants de 17 ans et moins.';
$t['The form to signup will not exists'] = 'The form to signup will not exists';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Le code cadeau a été annulé. Si cela vous semble anormal, veuillez contacter notre équipe d\'assistance.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Le code cadeau est actuellement inactif. Veuillez réessayer plus tard ou contacter l\'assistance.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Les informations ci-dessus correspondent à nos registres officiels et confirment l\'authenticité de ce certificat.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Le flux d\'entrée contient des données invalides. Le flux HLS source n\'est peut-être pas encore prêt ou le flux a été interrompu.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Le paquet PHP installé contient les deux correctifs, mais ce processus web exécute toujours la version chargée avant la mise à jour. Redémarrez Apache ou PHP-FPM.';
$t['Their last plans add up to %s'] = 'Leurs derniers forfaits totalisent %s';
$t['The list was limited to the first %s results.'] = 'La liste a été limitée aux %s premiers résultats.';
$t['The live service could not complete the request. Please try again.'] = 'Le service de live n\'a pas pu traiter la demande. Veuillez réessayer.';
$t['The live that was still being sent to this destination was stopped.'] = 'Le live qui était encore diffusé vers cette destination a été arrêté.';
$t['Theme for Style:'] = 'Theme for Style:';
$t['Themes'] = 'Thèmes';
$t['The number of lines in both columns must be the same'] = 'Le nombre de lignes doit être identique dans les deux colonnes';
$t['The original file for this video does not exists anymore'] = 'Le fichier original de cette vidéo n\'existe plus';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'The Permissions Plugin is not installed. Please install it if you want to customize the permissions.';
$t['The plugin is disabled'] = 'The plugin is disabled';
$t['The program is empty'] = 'The program is empty';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'L\'achat n\'a pas pu être finalisé. Le paiement n\'a pas été débité de votre portefeuille. Vérifiez votre solde avant de réessayer.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'Ce code cadeau a un statut inconnu. Veuillez contacter l\'assistance.';
$t['There, you can set'] = 'There, you can set';
$t['There are no notifications'] = 'Il n\'y a aucune notification';
$t['There are no upcoming events for this channel'] = 'Aucun événement à venir pour cette chaîne';
$t['There are various kinds of media you can integrate here. They are working different'] = 'There are various kinds of media you can integrate here. They are working different';
$t['The recover pass does not match!'] = 'Le passe de récupération ne correspond pas !';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'The regular form to signin will not exist, if you check this will only have social login or LDAP option';
$t['There is missing data to recover your password'] = 'Il manque des information pour récupérer ton mot de passe';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Il n\'existe encore aucun forfait Pay Per View. Créez-en un dans le plugin Pay-Per-View, onglet PPV Plans.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Aucun forfait ne peut encore contenir de vidéos. Créez-en un dans l\'onglet PPV Plans, puis revenez ici.';
$t['There is no streaming now'] = 'Il n\'y a pas de diffusion actuellement';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Le numéro de version et la version de la base de données AVideo sont indépendants. L\'état de mise à jour du code est déterminé par l\'historique des commits.';
$t['The request to the social network failed. Please try again later.'] = 'La requête vers le réseau social a échoué. Veuillez réessayer plus tard.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Le serveur de restreaming ne parvient pas à joindre la destination. Vérifiez la connectivité réseau.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'La même alerte est répétée au maximum toutes les %s tant que le problème persiste.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'La même alerte est répétée au maximum toutes les quelques heures tant que le problème persiste.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'La caméra ou le micro sélectionné n\'est pas disponible. Veuillez choisir un autre appareil.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'La position sélectionnée est mise en évidence sur une vraie page. L\'aperçu mobile ne modifie que les positions des publicités ; le reste de la page utilise l\'appareil de votre navigateur.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'L\'emplacement sélectionné est encadré sur une vraie page de votre site et suit l\'emplacement que vous choisissez ci-dessous. L\'aperçu mobile ne modifie que les emplacements des publicités ; le reste de la page utilise l\'appareil de votre navigateur.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Le site est actuellement hors ligne en raison d\'un problème de base de données. Nous travaillons à résoudre le problème au plus vite.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Le site est temporairement indisponible car le disque du serveur est plein. Nous travaillons sur ce problème et serons de retour très bientôt.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Le site est en maintenance car le disque du serveur est presque plein. Nous traitons le problème et serons de retour très bientôt.';
