$t['YouTube did not allow this upload. Reconnect your YouTube account and allow this website to manage your YouTube videos.'] = 'YouTube n\'a pas autorisé cette mise en ligne. Reconnectez votre compte YouTube et autorisez ce site à gérer vos vidéos YouTube.';
